const payload = $input.first()?.json || {};
const changes = payload.changes || [];
const byId = new Map();
for (const change of changes) {
  const id = change.record?.notionId || change.record?.linearId;
  if (id) byId.set(id, change);
}
const visited = new Set();
const active = new Set();
const ordered = [];
const errors = [];

function walk(change) {
  const id = change.record?.notionId || change.record?.linearId;
  if (!id || visited.has(id)) return;
  if (active.has(id)) {
    errors.push(`Cycle detected at ${id}`);
    return;
  }
  active.add(id);
  const parentId = change.record?.parentTaskNotionId || change.record?.parentTaskLinearId;
  if (parentId && byId.has(parentId)) {
    walk(byId.get(parentId));
  }
  active.delete(id);
  visited.add(id);
  ordered.push(change);
}

for (const change of changes) walk(change);
return [{ json: { changes: ordered, errors } }];
